 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let position = 0;
+  while (position < template.length) {
+    const open = template.indexOf("{{", position);
+    if (open === -1) {
+      tokens.push({ kind: "text", text: template.slice(position) });
+      break;
+    }
+    const raw = template.startsWith("{{{", open);
+    const closing = raw ? "}}}" : "}}";
+    const bodyStart = open + (raw ? 3 : 2);
+    const close = template.indexOf(closing, bodyStart);
+    if (close === -1) {
+      throw new Error("unterminated tag");
+    }
+    if (open > position) {
+      tokens.push({ kind: "text", text: template.slice(position, open) });
+    }
+    tokens.push(classify(template.slice(bodyStart, close).trim(), raw));
+    position = close + closing.length;
+  }
+  return tokens;
 }
+
+function classify(body: string, raw: boolean): Token {
+  if (raw) {
+    return { kind: "value", expr: body, raw: true };
+  }
+  if (body === "else") {
+    return { kind: "else" };
+  }
+  if (body === "/if") {
+    return { kind: "end" };
+  }
+  const conditional = /^#if(?:\s+(.*))?$/.exec(body);
+  if (conditional) {
+    return { kind: "if", path: (conditional[1] ?? "").trim() };
+  }
+  return { kind: "value", expr: body, raw: false };
+}
